<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { ArrowRight, BadgeCheck, Building2, CalendarDays, CircleDollarSign, ClipboardList, Users, Wrench } from 'lucide-vue-next'
import { api } from '../api'
import { useSessionStore } from '../stores/session'
const session = useSessionStore()
const loading = ref(true)
const overview = ref<any>(null)
const error = ref('')
onMounted(async () => { try { overview.value = (await api.get('/workspace/overview')).data } catch { error.value = 'Could not load workspace data. Check that the API is running.' } finally { loading.value = false } })
</script>

<template><section class="workspace-content"><div v-if="error" class="notice error-notice">{{ error }}</div><div v-if="loading" class="workspace-kpis"><div v-for="n in 4" :key="n" class="skeleton-kpi"></div></div><div v-else-if="overview" class="workspace-kpis"><article><span class="kpi-icon blue"><Building2 /></span><small>Properties</small><b>{{ overview.propertyCount }}</b><span class="kpi-note">In your workspace</span></article><article><span class="kpi-icon green"><CalendarDays /></span><small>{{ session.session?.user.role === 'TENANT' ? 'My viewings' : 'Scheduled viewings' }}</small><b>{{ overview.viewings }}</b><span class="kpi-note">Upcoming and completed</span></article><article><span class="kpi-icon orange"><ClipboardList /></span><small>{{ session.session?.user.role === 'TENANT' ? 'My leases' : 'Active leases' }}</small><b>{{ overview.leases }}</b><span class="kpi-note">Across your portfolio</span></article><article><span class="kpi-icon red"><Wrench /></span><small>Open maintenance</small><b>{{ overview.maintenanceOpen }}</b><span class="kpi-note">Requests in progress</span></article><article v-if="['ADMIN','AGENT','SALES_MANAGER'].includes(session.session?.user.role || '')"><span class="kpi-icon purple"><Users /></span><small>Sales leads</small><b>{{ overview.leadCount }}</b><span class="kpi-note">In your pipeline</span></article><article><span class="kpi-icon gold"><CircleDollarSign /></span><small>Rent invoices due</small><b>{{ overview.invoicesDue }}</b><span class="kpi-note">Outstanding obligations</span></article><article><span class="kpi-icon teal"><BadgeCheck /></span><small>Offers & applications</small><b>{{ overview.offers + overview.applications }}</b><span class="kpi-note">Waiting for a decision</span></article></div><div class="workspace-columns"><section class="panel-card"><div class="panel-heading"><div><h2>Pick up where you left off</h2><p>Shortcuts to your active workflows.</p></div></div><div class="shortcut-grid"><RouterLink v-if="['ADMIN','AGENT'].includes(session.session?.user.role || '')" to="/workspace/leads"><span class="shortcut-icon purple"><Users /></span><span><b>Review sales pipeline</b><small>Assign leads and record follow-ups</small></span><ArrowRight /></RouterLink><RouterLink to="/workspace/viewings"><span class="shortcut-icon blue"><CalendarDays /></span><span><b>Manage viewings</b><small>Request a time or confirm a visit</small></span><ArrowRight /></RouterLink><RouterLink v-if="['ADMIN','OWNER'].includes(session.session?.user.role || '')" to="/workspace/portfolio"><span class="shortcut-icon green"><Building2 /></span><span><b>Manage your properties</b><small>Portfolio, units, and availability</small></span><ArrowRight /></RouterLink><RouterLink to="/workspace/rent"><span class="shortcut-icon gold"><CircleDollarSign /></span><span><b>Rent and payments</b><small>Review invoices and payment history</small></span><ArrowRight /></RouterLink><RouterLink to="/workspace/maintenance"><span class="shortcut-icon orange"><Wrench /></span><span><b>Maintenance desk</b><small>Report a repair or track a work order</small></span><ArrowRight /></RouterLink><RouterLink to="/workspace/deals"><span class="shortcut-icon teal"><ClipboardList /></span><span><b>Offers and applications</b><small>See the latest activity on your listings</small></span><ArrowRight /></RouterLink></div></section><aside class="panel-card portfolio-card"><div class="eyebrow muted-eyebrow">UNIT MIX</div><h2>At a glance</h2><p>Track the spaces across your organization.</p><div v-for="unit in overview?.units || []" :key="unit.status" class="unit-mix"><span><i :class="unit.status.toLowerCase()"></i>{{ unit.status.toLowerCase() }}</span><b>{{ unit._count._all }}</b></div><div v-if="!overview?.units?.length" class="small-empty">Create units in your property portfolio to see occupancy here.</div><RouterLink v-if="['ADMIN','OWNER'].includes(session.session?.user.role || '')" class="text-link" to="/workspace/portfolio">Open portfolio <A